-- 0055 — Treizième lot de recettes du catalogue (publiées et validées) :
-- desserts équilibrés, fruits de saison et peu de sucre ajouté (calcul Ciqual).
-- Fichier GÉNÉRÉ par scripts/generate-recipes-lot13.py depuis scripts/data/recipes-lot13.py.
-- Recettes originales (D7). Ne jamais éditer une fois appliqué.
-- 20 recettes, 144 lignes d'ingrédients, 106 étapes.

insert into public.recipes (slug, title, description, storage_note, servings, prep_minutes,
  cook_minutes, tags, status, source, source_ref, validated_at)
select v.slug, v.title, v.description, v.storage, v.servings, v.prep, v.cook, v.tags,
  'published', 'curated', 'Aux Petits Oignons — recette originale', now()
from (values
  ('poires-roties-miel-fromage-blanc', 'Poires rôties au miel, fromage blanc et noix', 'Des demi-poires rôties au four avec un filet de miel et de la cannelle, servies tièdes sur du fromage blanc avec quelques noix concassées. Un dessert d''automne tout simple.', 'Les poires rôties se gardent 3 jours au réfrigérateur ; les réchauffer quelques minutes au four.', 4, 10, 25, array['dessert', 'four', 'economique']::text[]),
  ('crumble-pommes-avoine-leger', 'Crumble léger aux pommes et flocons d''avoine', 'Des pommes fondantes à la cannelle sous une pâte croustillante de flocons d''avoine, d''amandes et d''un peu de beurre, beaucoup moins sucrée que le crumble classique.', 'Se garde 3 jours au réfrigérateur. Se réchauffe 10 minutes au four pour retrouver le croustillant.', 4, 15, 30, array['dessert', 'four', 'economique']::text[]),
  ('mousse-fromage-blanc-citron', 'Mousse légère au fromage blanc et citron', 'Une mousse aérienne de fromage blanc parfumée au zeste et au jus de citron, allégée par des blancs d''œufs montés et à peine sucrée au miel. Fraîche et vive.', 'Se garde 2 jours au réfrigérateur, bien couverte.', 4, 15, 0, array['dessert', 'sans-cuisson']::text[]),
  ('clafoutis-pommes-leger', 'Clafoutis léger aux pommes', 'Des quartiers de pommes poêlés à la cannelle, noyés dans un appareil au lait et aux œufs peu sucré, cuit au four jusqu''à être doré et tremblotant.', 'Se garde 3 jours au réfrigérateur.', 4, 15, 35, array['dessert', 'four', 'economique']::text[]),
  ('creme-aux-oeufs-vanille', 'Petites crèmes aux œufs à la vanille', 'Des crèmes aux œufs et au lait parfumées à la vanille, cuites doucement au bain-marie au four. Un dessert d''enfance, peu sucré et riche en protéines.', 'Se gardent 3 jours au réfrigérateur, couvertes.', 4, 10, 35, array['dessert', 'four', 'economique']::text[]),
  ('banana-bread-avoine', 'Banana bread aux flocons d''avoine', 'Un cake moelleux aux bananes bien mûres et aux flocons d''avoine, sucré presque uniquement par les fruits, avec des noix. Parfait pour finir les bananes tachées.', 'Se garde 4 jours dans une boîte et se congèle en tranches.', 8, 15, 45, array['dessert', 'four', 'economique']::text[]),
  ('semoule-au-lait-orange', 'Semoule au lait à l''orange', 'Une semoule fine cuite doucement dans le lait avec le zeste d''une orange et un peu de sucre, servie avec des suprêmes d''orange. Réconfortant et parfumé.', 'Se garde 3 jours au réfrigérateur ; ajouter les oranges au moment de servir.', 4, 10, 15, array['dessert', 'economique']::text[]),
  ('verrines-fromage-blanc-pomme-caramelisee', 'Verrines de fromage blanc et pommes caramélisées', 'Des dés de pomme caramélisés à la poêle avec un peu de miel et de cannelle, sur du fromage blanc, avec des flocons d''avoine grillés et des noix.', 'Les pommes se gardent 3 jours au réfrigérateur ; monter les verrines au moment de servir.', 4, 10, 10, array['dessert', 'economique']::text[]),
  ('poelee-pommes-poires-cannelle-yaourt', 'Poêlée de pommes et poires à la cannelle, yaourt', 'Des quartiers de pommes et de poires poêlés au beurre et à la cannelle avec quelques raisins secs, servis chauds avec un yaourt nature bien frais.', 'Les fruits se gardent 2 jours au réfrigérateur et se réchauffent à la poêle.', 4, 10, 10, array['dessert', 'economique']::text[]),
  ('gateau-pommes-yaourt-avoine', 'Gâteau aux pommes, yaourt et avoine', 'Un gâteau moelleux au yaourt et aux flocons d''avoine, garni de lamelles de pomme, avec peu de sucre et d''huile. Le gâteau du goûter, version plus équilibrée.', 'Se garde 3 jours dans une boîte.', 8, 15, 40, array['dessert', 'four', 'economique']::text[]),
  ('mousse-chocolat-fromage-blanc', 'Mousse au chocolat noir et fromage blanc', 'Une mousse au chocolat noir allégée au fromage blanc et aux blancs d''œufs, intense en chocolat mais bien plus légère que la mousse classique.', 'Se garde 2 jours au réfrigérateur, bien couverte.', 4, 20, 3, array['dessert']::text[]),
  ('brownie-haricots-rouges-chocolat', 'Brownie au chocolat et aux haricots rouges', 'Un brownie fondant où les haricots rouges remplacent la farine et une partie du beurre. On ne les devine pas, et le gâteau gagne fibres et protéines.', 'Se garde 4 jours au réfrigérateur dans une boîte.', 8, 15, 25, array['dessert', 'four']::text[]),
  ('glace-banane-cacao', 'Glace minute à la banane et au cacao', 'Des bananes congelées en rondelles mixées avec du yaourt et du cacao : une glace onctueuse en 5 minutes, sans sorbetière et sans sucre ajouté.', 'Se garde 1 semaine au congélateur ; la sortir 10 minutes avant de servir.', 4, 5, 0, array['dessert', 'sans-cuisson']::text[]),
  ('pommes-farcies-noix-raisins-secs', 'Pommes au four farcies aux noix et raisins secs', 'Des pommes évidées et farcies de noix, de raisins secs, de flocons d''avoine et de cannelle, rôties au four jusqu''à être fondantes, servies avec du fromage blanc.', 'Se gardent 2 jours au réfrigérateur.', 4, 15, 35, array['dessert', 'four', 'economique']::text[]),
  ('cheesecake-fromage-blanc-citron', 'Cheesecake léger au fromage blanc et citron', 'Un cheesecake au fromage blanc et au citron sur un fond croustillant d''avoine, d''amandes et de miel, cuit doucement au four. Beaucoup plus léger que la version au fromage frais.', 'Se garde 4 jours au réfrigérateur.', 8, 20, 45, array['dessert', 'four']::text[]),
  ('mug-cake-banane-cacao', 'Mug cake à la banane et au cacao', 'Un petit gâteau individuel cuit en une minute et demie au micro-ondes, à la banane écrasée, aux flocons d''avoine et au cacao, sans sucre ajouté.', 'À manger tout de suite.', 2, 5, 2, array['dessert', 'economique']::text[]),
  ('bouchees-avoine-noix-raisins', 'Bouchées à l''avoine, noix et raisins secs', 'Des petites boules sans cuisson de flocons d''avoine, noix, raisins secs, cacao et un peu de miel, à grignoter au dessert ou au goûter.', 'Se gardent 1 semaine au réfrigérateur dans une boîte.', 8, 15, 0, array['dessert', 'sans-cuisson']::text[]),
  ('poires-pochees-orange-cannelle', 'Poires pochées au jus d''orange et à la cannelle', 'Des poires entières pochées doucement dans du jus d''orange avec de la cannelle et de la vanille, servies tièdes avec un yaourt et leur sirop réduit.', 'Se gardent 4 jours au réfrigérateur dans leur sirop.', 4, 10, 30, array['dessert', 'economique']::text[]),
  ('gratin-pommes-poires-amandes', 'Gratin de pommes et poires aux amandes', 'Des fruits d''automne en lamelles nappés d''une crème légère aux œufs, au lait et à la poudre d''amandes, gratinés au four. Entre le flan et le gratin de fruits.', 'Se garde 2 jours au réfrigérateur.', 4, 15, 25, array['dessert', 'four']::text[]),
  ('muffins-pomme-avoine', 'Muffins à la pomme et aux flocons d''avoine', 'Des muffins moelleux aux dés de pomme, aux flocons d''avoine et au yaourt, peu sucrés et parfumés à la cannelle. À emporter facilement pour le goûter.', 'Se gardent 3 jours dans une boîte et se congèlent.', 12, 15, 22, array['dessert', 'four', 'economique']::text[])
) as v(slug, title, description, storage, servings, prep, cook, tags);

