insert into public.recipe_steps (recipe_id, position, instruction)
select r.id, v.pos, v.instruction
from (values
  ('poires-roties-miel-fromage-blanc', 1, 'Préchauffer le four à 190 °C.'),
  ('poires-roties-miel-fromage-blanc', 2, 'Couper les poires en deux, retirer le cœur et les poser dans un plat, face coupée vers le haut.'),
  ('poires-roties-miel-fromage-blanc', 3, 'Déposer un petit morceau de beurre sur chaque demi-poire, arroser de miel et saupoudrer de cannelle.'),
  ('poires-roties-miel-fromage-blanc', 4, 'Enfourner 25 minutes : les poires doivent être fondantes et légèrement dorées.'),
  ('poires-roties-miel-fromage-blanc', 5, 'Servir les poires tièdes sur le fromage blanc, avec leur jus et les noix concassées.'),
  ('crumble-pommes-avoine-leger', 1, 'Préchauffer le four à 190 °C.'),
  ('crumble-pommes-avoine-leger', 2, 'Éplucher les pommes, les couper en dés et les mélanger avec le jus de citron et la cannelle dans un plat.'),
