join public.recipes r on r.slug = v.recipe;

-- Garde-fou : une jointure silencieusement vide (slug introuvable) fait échouer la migration.
do $$
begin
  if (select count(*) from public.recipe_ingredients ri join public.recipes r on r.id = ri.recipe_id
      where r.slug in ('poires-roties-miel-fromage-blanc', 'crumble-pommes-avoine-leger', 'mousse-fromage-blanc-citron', 'clafoutis-pommes-leger', 'creme-aux-oeufs-vanille', 'banana-bread-avoine', 'semoule-au-lait-orange', 'verrines-fromage-blanc-pomme-caramelisee', 'poelee-pommes-poires-cannelle-yaourt', 'gateau-pommes-yaourt-avoine', 'mousse-chocolat-fromage-blanc', 'brownie-haricots-rouges-chocolat', 'glace-banane-cacao', 'pommes-farcies-noix-raisins-secs', 'cheesecake-fromage-blanc-citron', 'mug-cake-banane-cacao', 'bouchees-avoine-noix-raisins', 'poires-pochees-orange-cannelle', 'gratin-pommes-poires-amandes', 'muffins-pomme-avoine')) <> 144 then
    raise exception 'Lignes d''ingrédients manquantes dans le treizième lot de recettes.';
  end if;
end;
$$;
